// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum Attachment {
    
    case photo(url: String, width: UInt32?, height: UInt32?
    )
    case audio(artist: String, title: String, durationSec: UInt32, url: String?
    )
    case document(title: String, url: String, ext: String
    )
    case sticker(url: String
    )
    case link(title: String, url: String
    )
    case video(id: Int64, ownerId: Int64, accessKey: String?, title: String, durationSec: UInt32, thumbnailUrl: String?, playerUrl: String?, streamUrl: String?, qualities: [VideoQualityOption]
    )
    case audioMessage(url: String, durationSec: UInt32, transcript: String?
    )
    case poll(id: Int64, ownerId: Int64, question: String, answers: [PollAnswer]
    )
    case reply(messageId: Int64, text: String
    )
    case forwarded(fromName: String, text: String, date: Int64
    )
    case botKeyboard(inline: Bool, oneTime: Bool, rows: [BotKeyboardRow]
    )
    case unknown(kind: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAttachment: FfiConverterRustBuffer {
    typealias SwiftType = Attachment

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Attachment {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .photo(url: try FfiConverterString.read(from: &buf), width: try FfiConverterOptionUInt32.read(from: &buf), height: try FfiConverterOptionUInt32.read(from: &buf)
        )
        
        case 2: return .audio(artist: try FfiConverterString.read(from: &buf), title: try FfiConverterString.read(from: &buf), durationSec: try FfiConverterUInt32.read(from: &buf), url: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 3: return .document(title: try FfiConverterString.read(from: &buf), url: try FfiConverterString.read(from: &buf), ext: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .sticker(url: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .link(title: try FfiConverterString.read(from: &buf), url: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .video(id: try FfiConverterInt64.read(from: &buf), ownerId: try FfiConverterInt64.read(from: &buf), accessKey: try FfiConverterOptionString.read(from: &buf), title: try FfiConverterString.read(from: &buf), durationSec: try FfiConverterUInt32.read(from: &buf), thumbnailUrl: try FfiConverterOptionString.read(from: &buf), playerUrl: try FfiConverterOptionString.read(from: &buf), streamUrl: try FfiConverterOptionString.read(from: &buf), qualities: try FfiConverterSequenceTypeVideoQualityOption.read(from: &buf)
        )
        
        case 7: return .audioMessage(url: try FfiConverterString.read(from: &buf), durationSec: try FfiConverterUInt32.read(from: &buf), transcript: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 8: return .poll(id: try FfiConverterInt64.read(from: &buf), ownerId: try FfiConverterInt64.read(from: &buf), question: try FfiConverterString.read(from: &buf), answers: try FfiConverterSequenceTypePollAnswer.read(from: &buf)
        )
        
        case 9: return .reply(messageId: try FfiConverterInt64.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .forwarded(fromName: try FfiConverterString.read(from: &buf), text: try FfiConverterString.read(from: &buf), date: try FfiConverterInt64.read(from: &buf)
        )
        
        case 11: return .botKeyboard(inline: try FfiConverterBool.read(from: &buf), oneTime: try FfiConverterBool.read(from: &buf), rows: try FfiConverterSequenceTypeBotKeyboardRow.read(from: &buf)
        )
        
        case 12: return .unknown(kind: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Attachment, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .photo(url,width,height):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(url, into: &buf)
            FfiConverterOptionUInt32.write(width, into: &buf)
            FfiConverterOptionUInt32.write(height, into: &buf)
            
        
        case let .audio(artist,title,durationSec,url):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(artist, into: &buf)
            FfiConverterString.write(title, into: &buf)
            FfiConverterUInt32.write(durationSec, into: &buf)
            FfiConverterOptionString.write(url, into: &buf)
            
        
        case let .document(title,url,ext):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(title, into: &buf)
            FfiConverterString.write(url, into: &buf)
            FfiConverterString.write(ext, into: &buf)
            
        
        case let .sticker(url):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(url, into: &buf)
            
        
        case let .link(title,url):
