            )
        case 9: return .RateLimited
        case 10: return .Internal(
            details: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: VkError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .InvalidToken:
            writeInt(&buf, Int32(1))
        
        
        case let .ValidationRequired(validationType,phoneMask):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(validationType, into: &buf)
            FfiConverterString.write(phoneMask, into: &buf)
            
        
